 39	/** First server-configured reply model wins. No browser-supplied model keys. */
 40	function envProvider(): { slug: AiProviderSlug; key: string } | null {
 41	  const order: AiProviderSlug[] = ["anthropic", "openai", "groq", "mistral", "xai"];
 42	  for (const slug of order) {
 43	    const key = process.env[PROVIDER_ENV[slug]] ?? "";
 44	    if (key && CLOUD_ENDPOINT[slug]) return { slug, key };
 45	  }
 46	  return null;
 47	}
