 49	async function settleInbound(
 50	  supabase: SupabaseClient,
 51	  inboundId: string,
 52	  claimId: string,
 53	  outcome: "processed" | "triage" | "retry",
 54	  reason?: string,
 55	): Promise<boolean> {
 56	  const { data, error } = await supabase.rpc("complete_whatsapp_inbound_processing", {
 57	    p_inbound_id: inboundId,
 58	    p_claim_id: claimId,
 59	    p_outcome: outcome,
 60	    p_error: reason ?? null,
 61	  });
 62	  const result = data as { ok?: boolean } | null;
 63	  if (!error && result?.ok === true) return true;
 64	  safeLog("whatsapp inbound: completion update failed", { message: error?.message ?? "no result", outcome });
 65	  return false;
 66	}
