 68	/** Compose exactly once for a durable inbound row. A lease-backed database claim
 69	 * prevents duplicate LLM calls when Meta redelivers while recovery is running. */
 70	export async function processStoredWhatsAppInbound(
 71	  supabase: SupabaseClient,
 72	  input: { inboundId: string; senderId: string },
 73	): Promise<WhatsAppInboundProcessResult> {
 74	  const { data, error } = await supabase.rpc("claim_whatsapp_inbound_processing", {
 75	    p_inbound_id: input.inboundId,
 76	    p_sender_id: input.senderId,
 77	  });
 78	  const claim = data as InboundClaim | null;
 79	  if (error || claim?.ok !== true) {
 80	    const reason = error?.message ?? claim?.reason ?? "claim-failed";
 81	    const isBenign = claim?.reason === "already-processed" || claim?.reason === "already-claimed";
 82	    if (!isBenign) safeLog("whatsapp inbound: processing claim failed", { message: reason });
 83	    return { outcome: isBenign ? "skipped" : "retry", reason };
 84	  }
 85	
 86	  const claimId = claim.claim_id;
 87	  const workspaceId = claim.workspace_id;
 88	  const senderId = claim.sender_id;
 89	  const recipient = claim.from_address;
 90	  const body = claim.body;
 91	  const providerId = claim.provider_id;
 92	  const receivedAt = claim.received_at;
 93	  if (!claimId || !workspaceId || !senderId || !recipient || typeof body !== "string" || !receivedAt) {
 94	    const settled = claimId
 95	      ? await settleInbound(supabase, input.inboundId, claimId, "retry", "incomplete-processing-claim")
 96	      : false;
 97	    return { outcome: settled ? "retry" : "retry", reason: "incomplete-processing-claim" };
 98	  }
 99	
100	  const complete = async (outcome: "processed" | "triage", reason?: string): Promise<WhatsAppInboundProcessResult> => {
101	    const settled = await settleInbound(supabase, input.inboundId, claimId, outcome, reason);
102	    return settled
103	      ? { outcome, reason: reason ?? outcome }
104	      : { outcome: "retry", reason: "completion-update-failed" };
105	  };
106	  const retry = async (reason: string): Promise<WhatsAppInboundProcessResult> => {
107	    await settleInbound(supabase, input.inboundId, claimId, "retry", reason);
108	    return { outcome: "retry", reason };
109	  };
110	
111	  try {
112	    if (isWhatsAppOptOut(body)) {
113	      const { error: contactErr } = await supabase.from("whatsapp_contacts").upsert(
114	        {
115	          workspace_id: workspaceId,
116	          recipient_e164: recipient,
117	          consent_status: "opted_out",
118	          consent_source: "candidate-message",
119	          consent_evidence: { provider_message_id: providerId },
120	          recorded_at: receivedAt,
121	          expires_at: null,
122	          revoked_at: receivedAt,
123	          revoked_reason: "candidate-opt-out",
124	          last_inbound_at: receivedAt,
125	        },
126	        { onConflict: "workspace_id,recipient_e164" },
127	      );
128	      if (contactErr) return retry("opt-out-contact-write-failed");
129	
130	      const { error: suppressErr } = await supabase.from("suppression_list").upsert(
131	        {
132	          workspace_id: workspaceId,
133	          type: "phone",
134	          value: recipient,
135	          reason: "Candidate requested WhatsApp opt-out.",
136	          source: "WhatsApp candidate message",
137	        },
138	        { onConflict: "workspace_id,type,value" },
139	      );
140	      if (suppressErr) return retry("opt-out-suppression-write-failed");
141	
142	      const { error: cancelErr } = await supabase
143	        .from("messages_outbound")
144	        .update({ status: "blocked", gate_result: { pass: false, reasons: ["whatsapp:opted-out"] } })
145	        .eq("workspace_id", workspaceId)
146	        .eq("channel", "WhatsApp")
147	        .eq("recipient_e164", recipient)
148	        .in("status", ["composed", "queued"]);
149	      if (cancelErr) return retry("opt-out-cancellation-failed");
150	      return complete("processed", "opt-out-recorded");
151	    }
152	
153	    const { error: contactErr } = await supabase
154	      .from("whatsapp_contacts")
155	      .update({ last_inbound_at: receivedAt })
156	      .eq("workspace_id", workspaceId)
157	      .eq("recipient_e164", recipient)
158	      .eq("consent_status", "opted_in");
159	    if (contactErr) return retry("contact-window-update-failed");
160	
161	    const windowEnd = new Date(new Date(receivedAt).getTime() + 24 * 60 * 60 * 1_000).toISOString();
162	    const { error: windowErr } = await supabase.from("whatsapp_conversation_windows").upsert(
163	      {
164	        workspace_id: workspaceId,
165	        sender_id: senderId,
166	        recipient_e164: recipient,
167	        last_inbound_message_id: providerId ?? input.inboundId,
168	        last_inbound_at: receivedAt,
169	        freeform_until: windowEnd,
170	      },
171	      { onConflict: "workspace_id,sender_id,recipient_e164" },
172	    );
173	    if (windowErr) return retry("reply-window-write-failed");
174	
175	    const { data: thread, error: threadErr } = await supabase
176	      .from("messages_outbound")
177	      .select("candidate_id, spec_id, body")
178	      .eq("workspace_id", workspaceId)
179	      .eq("to_address", recipient)
180	      .order("created_at", { ascending: false })
181	      .limit(1)
182	      .maybeSingle();
183	    if (threadErr) return retry("thread-lookup-failed");
184	    if (!thread?.spec_id) return complete("triage", "no-active-thread");
185	
186	    const { data: spec, error: specErr } = await supabase
187	      .from("agent_specs")
188	      .select("id, seat_id, role_brief, guardrails, status")
189	      .eq("id", thread.spec_id)
190	      .maybeSingle();
191	    if (specErr) return retry("agent-spec-lookup-failed");
192	    if (!spec || spec.status !== "active") return complete("triage", "agent-spec-unavailable");
193	
194	    const provider = envProvider();
195	    if (!provider) return retry("reply-provider-unavailable");
196	    const brief = spec.role_brief as { title?: string; seniority?: string } & Record<string, unknown>;
197	    const { system, prompt } = buildReplyPrompt({
198	      inbound: body,
199	      lastOutbound: thread.body,
200	      roleSummary: JSON.stringify(brief).slice(0, 2_000),
201	    });
202	    const request = buildCloudRequest(provider.slug, DEFAULT_MODEL[provider.slug], system, prompt, provider.key, 512);
203	    const response = await fetch(request.url, {
204	      method: "POST",
205	      headers: request.headers,
206	      body: request.body,
207	      signal: AbortSignal.timeout(30_000),
208	    });
209	    if (!response.ok) return retry("reply-provider-failed");
210	    const draft = parseCloudResponse(provider.slug, await response.json());
211	    if (!draft.trim()) return retry("empty-reply-draft");
212	
213	    const guardrails = (spec.guardrails ?? {}) as SpecGuardrails;
214	    const decision = decideAutopilot(draft, guardrails);
215	    const reviewDraftDedupeHash = dedupeHash(thread.candidate_id, "WhatsApp", decision.text);
216	    const { error: outboundErr } = await supabase.from("messages_outbound").insert({
217	      workspace_id: workspaceId,
218	      inbound_message_id: input.inboundId,
219	      spec_id: spec.id,
220	      candidate_id: thread.candidate_id,
221	      seat_id: spec.seat_id,
222	      channel: "WhatsApp",
223	      to_address: recipient,
224	      recipient_e164: recipient,
225	      type: "candidate_reply",
226	      body: decision.text,
227	      status: "blocked",
228	      gate_result: { pass: false, reasons: decision.reasons },
229	      dedupe_hash: reviewDraftDedupeHash,
230	      scheduled_at: null,
231	    });
232	    if (outboundErr?.code === "23505") {
233	      // A unique conflict only proves idempotency when the previously stored
234	      // review row belongs to this exact inbound event. A same-text collision
235	      // from another candidate reply must remain visible for manual triage.
236	      const { data: existingDraft, error: existingDraftErr } = await supabase
237	        .from("messages_outbound")
238	        .select("inbound_message_id")
239	        .eq("workspace_id", workspaceId)
240	        .eq("inbound_message_id", input.inboundId)
241	        .maybeSingle();
242	      if (existingDraftErr) return retry("review-draft-conflict-lookup-failed");
243	      if (existingDraft?.inbound_message_id !== input.inboundId) {
244	        return complete("triage", "review-draft-dedupe-conflict");
245	      }
246	    } else if (outboundErr) {
247	      return retry("review-draft-write-failed");
248	    }
249	
250	    if (guardrails.autopilot && (guardrails.canary_remaining ?? 0) > 0) {
251	      const { error: canaryErr } = await supabase
252	        .from("agent_specs")
253	        .update({ guardrails: { ...guardrails, canary_remaining: (guardrails.canary_remaining ?? 0) - 1 } })
254	        .eq("id", spec.id);
255	      if (canaryErr) safeLog("whatsapp inbound: canary update failed", { message: canaryErr.message });
256	    }
257	    return complete("processed");
258	  } catch (err) {
259	    safeLog("whatsapp inbound: processing error", { message: err instanceof Error ? err.message : "unknown" });
260	    return retry("unexpected-processing-error");
261	  }
262	}
