264	/** Daily and webhook-triggered backstop for rows whose first processing attempt
265	 * failed after durable storage. Rows without a safe sender mapping are never
266	 * guessed and remain for manual triage. */
267	export async function recoverPendingWhatsAppInbound(
268	  supabase: SupabaseClient,
269	  limit = 10,
270	): Promise<{ attempted: number; recovered: number; retryable: number }> {
271	  const boundedLimit = Math.max(1, Math.min(50, Math.floor(limit)));
272	  const now = new Date().toISOString();
273	  const { data, error } = await supabase
274	    .from("messages_inbound")
275	    .select("id, whatsapp_sender_id")
276	    .eq("channel", "WhatsApp")
277	    .eq("processed", false)
278	    .not("whatsapp_sender_id", "is", null)
279	    .or(`processing_lease_until.is.null,processing_lease_until.lte.${now}`)
280	    .order("received_at", { ascending: true })
281	    .limit(boundedLimit);
282	  if (error) {
283	    safeLog("whatsapp inbound: recovery select failed", { message: error.message });
284	    return { attempted: 0, recovered: 0, retryable: 1 };
285	  }
286	
287	  let attempted = 0;
288	  let recovered = 0;
289	  let retryable = 0;
290	  for (const row of (data ?? []) as StoredInboundRow[]) {
291	    if (!row.whatsapp_sender_id) continue;
292	    attempted++;
293	    const result = await processStoredWhatsAppInbound(supabase, { inboundId: row.id, senderId: row.whatsapp_sender_id });
294	    if (result.outcome === "processed" || result.outcome === "triage") recovered++;
295	    if (result.outcome === "retry") retryable++;
296	  }
297	  return { attempted, recovered, retryable };
298	}

