113	
114	  const limit = checkRateLimit(rateLimitKey(req, "careers-public-read"), { windowMs: 60_000, max: 120 });
115	  if (!limit.ok) return limitedResponse(limit.retryAfterSec);
116	
117	  const repository = serviceRepository();
118	  if (!repository) return json({ ok: false }, 503);
119	  try {
120	    const jobs = await loadPublicCareerJobs(repository, workspaceId);
121	    if (!jobs) return json({ ok: false }, 503);
