113	// ---------------------------------------------------------------------------
114	// Pacing — humans don't answer at 3:12 AM in 400ms.
115	// ---------------------------------------------------------------------------
116	export interface QuietHours {
117	  /** Local hour 0-23, inclusive start of the quiet window (e.g. 21). */
118	  start: number;
119	  /** Local hour 0-23, exclusive end of the quiet window (e.g. 8). */
120	  end: number;
121	}
122	
123	export const DEFAULT_QUIET_HOURS: QuietHours = { start: 21, end: 8 };
124	
125	/** True when `date` falls inside the quiet window (window may wrap midnight). */
126	export function inQuietHours(date: Date, quiet: QuietHours = DEFAULT_QUIET_HOURS): boolean {
127	  const h = date.getHours();
128	  return quiet.start <= quiet.end
129	    ? h >= quiet.start && h < quiet.end
130	    : h >= quiet.start || h < quiet.end;
131	}
132	
133	/** Earliest human-plausible send time: now + jittered delay, pushed out of quiet hours. */
134	export function nextSendTime(now: Date, seed: string, quiet: QuietHours = DEFAULT_QUIET_HOURS): Date {
135	  const at = new Date(now.getTime() + replyDelayMs(seed));
136	  if (!inQuietHours(at, quiet)) return at;
137	  // Defer to the end of the quiet window (same day or next).
138	  const resumed = new Date(at);
139	  resumed.setHours(quiet.end, 0, 0, 0);
140	  if (resumed <= at) resumed.setDate(resumed.getDate() + 1);
141	  // Re-apply a fresh jitter so unblocked messages don't all fire at HH:00:00.
142	  return new Date(resumed.getTime() + replyDelayMs(seed + ":resume"));
143	}
144	
145	/**
146	 * Deterministic jitter in [90s, 480s] derived from a seed (e.g. the message
147	 * id) — feels like a person typing, is reproducible in tests, and spreads
148	 * concurrent replies apart.
149	 */
150	export function replyDelayMs(seed: string): number {
151	  const digest = createHash("sha256").update(seed).digest();
152	  const fraction = digest.readUInt32BE(0) / 0xffffffff;
153	  const min = 90_000;
154	  const max = 480_000;
155	  return Math.floor(min + fraction * (max - min));
156	}

