22	/** Null signals a missing or unreadable configured workspace, never a demo fallback. */
23	export async function loadPublicCareerJobs(
24	  repository: CareerWorkspaceRepository,
25	  workspaceId: string,
26	): Promise<PublicCareerJob[] | null> {
27	  const row = await repository.load(workspaceId);
28	  return row ? publicCareerJobsFromState(row.state) : null;
29	}
