31	/**
32	 * Append a validated application using optimistic concurrency. The public caller
33	 * never writes a raw workspace blob and cannot choose a non-public campaign.
34	 */
35	export async function submitPublicCareerApplication(
36	  repository: CareerWorkspaceRepository,
37	  workspaceId: string,
38	  input: PublicCareerApplicationInput,
39	  createdAt = new Date().toISOString(),
40	): Promise<PublicCareerSubmissionResult> {
41	  for (let attempt = 0; attempt < 2; attempt += 1) {
42	    const row = await repository.load(workspaceId);
43	    if (!row) return "unavailable";
44	
45	    const publicJobs = publicCareerJobsFromState(row.state);
46	    const submission = buildPublicCareerSubmission(input, publicJobs, createdAt);
47	    if (!submission) return "invalid";
48	
49	    const existing = row.state.chatboxSubmissions;
50	    if (existing !== undefined && !Array.isArray(existing)) return "unavailable";
51	    const submissions = Array.isArray(existing) ? existing : [];
52	    if (isRecentCareerSubmissionDuplicate(submissions, submission, createdAt)) return "duplicate";
53	
54	    const saved = await repository.compareAndSet(workspaceId, row.updatedAt, {
55	      ...row.state,
56	      chatboxSubmissions: [submission, ...submissions],
57	    });
58	    if (saved) return "accepted";
59	  }
60	  return "unavailable";
61	}

