 18	/**
 19	 * Agentic sourcing: one tool-calling loop that searches real platforms, scores
 20	 * real candidates (deterministic — see sourcing-tools.ts), and drafts outreach
 21	 * for the best matches, instead of the client stitching separate calls one at
 22	 * a time. TEXT + TOOL CALLS ONLY — like /api/hermes/chat, this never sends
 23	 * anything; drafts still go through the same human approval gate as any other
 24	 * outreach message.
 25	 *
 26	 * Only providers with real function-calling get this (no "hermes"/"kimi" — the
 27	 * hermes runtime path and Kimi Code don't support the tools param).
 28	 */
 29	const AGENT_PROVIDERS = ["anthropic", "openai", "groq", "xai", "mistral"] as const;
