 31	const SourcingAgentSchema = z.object({
 32	  // Full client-owned objects, passed through — the client already has these
 33	  // in its local state; this route is stateless per-request, same posture as
 34	  // /api/source (which receives a client-built query string rather than
 35	  // looking up campaign data server-side).
 36	  campaign: z.record(z.string(), z.unknown()),
 37	  existing: z.array(z.record(z.string(), z.unknown())).max(500).default([]),
 38	  count: z.number().int().min(1).max(8).default(5),
 39	  provider: z.enum(AGENT_PROVIDERS),
 40	  apiKeyId: z.string().uuid().optional(),
 41	  model: z.string().regex(/^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$/).optional(),
 42	});
