 44	const SYSTEM_PROMPT =
 45	  "You are Aria's autonomous sourcing agent. You have a search_candidates tool that returns REAL, " +
 46	  "already-scored people found via real platform search — you never invent a candidate, a score, a " +
 47	  "company, or a URL. Call it across the platforms that make sense for this role (skip ones with no " +
 48	  "real fit — e.g. don't search Dribbble for a backend engineer). Call it more than once per platform " +
 49	  "with a different query if the first pass returns too few strong matches. Once you've gathered enough " +
 50	  "real, well-scored candidates, stop calling tools and respond with ONLY this JSON (no prose, no markdown " +
 51	  "fences): {\"drafts\": [{\"candidateId\": \"<id from a tool result>\", \"subject\": \"<email subject>\", " +
 52	  "\"body\": \"<first-touch outreach, under 120 words, leads with their specific real work, one genuine " +
 53	  "reason for reaching out, soft low-pressure ask, no AI slop, no corporate filler, no em-dashes>\"}]}. " +
 54	  "Draft for the requested number of candidates, choosing the best-scored real matches you found. Every " +
 55	  "candidateId MUST be one that a search_candidates result actually returned.";
 56	
 57	function buildPrompt(campaign: Campaign, count: number): string {
 58	  const jd = campaign.jobAnalysis;
 59	  return [
 60	    `Role: ${jd.title} (${jd.seniority}, ${jd.department})`,
 61	    `Location: ${jd.locationType}${jd.regions.length ? ` — ${jd.regions.join("/")}` : ""}`,
 62	    `Required skills: ${jd.requiredSkills.join(", ") || "n/a"}`,
 63	    `Nice-to-have: ${jd.niceToHaveSkills.join(", ") || "n/a"}`,
 64	    jd.minYearsExperience != null ? `Minimum experience: ${jd.minYearsExperience} years` : "",
 65	    jd.companyStageTarget.length ? `Target company stage: ${jd.companyStageTarget.join(", ")}` : "",
 66	    jd.industryExperience.length ? `Industry experience: ${jd.industryExperience.join(", ")}` : "",
 67	    "",
 68	    `Find and draft outreach for ${count} real candidates for this role.`,
 69	  ]
 70	    .filter(Boolean)
 71	    .join("\n");
 72	}
