 74	/** Parse the model's final JSON, tolerant of stray text/markdown fences around it. */
 75	function parseDrafts(text: string): { candidateId: string; subject: string; body: string }[] {
 76	  const match = text.match(/\{[\s\S]*\}/);
 77	  if (!match) return [];
 78	  try {
 79	    const parsed = JSON.parse(match[0]) as { drafts?: unknown };
 80	    if (!Array.isArray(parsed.drafts)) return [];
 81	    return parsed.drafts
 82	      .filter(
 83	        (d): d is { candidateId: string; subject: string; body: string } =>
 84	          !!d &&
 85	          typeof d === "object" &&
 86	          typeof (d as Record<string, unknown>).candidateId === "string" &&
 87	          typeof (d as Record<string, unknown>).subject === "string" &&
 88	          typeof (d as Record<string, unknown>).body === "string",
 89	      )
 90	      .map((d) => ({ candidateId: d.candidateId, subject: d.subject.slice(0, 255), body: d.body.slice(0, 5_000) }));
 91	  } catch {
 92	    return [];
 93	  }
 94	}
