 96	export async function POST(req: NextRequest) {
 97	  const prodBlock = prodFailClosed();
 98	  if (prodBlock) return prodBlock;
 99	
100	  const supabase = supabaseEnabled ? await getServerSupabase() : null;
101	  let userId: string | null = null;
102	  if (supabaseEnabled) {
103	    if (!supabase) return NextResponse.json({ ok: false, reason: "No Supabase client." }, { status: 500 });
104	    const {
105	      data: { user },
106	    } = await supabase.auth.getUser();
107	    if (!user) return NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 });
108	    userId = user.id;
109	    const { data: role } = await supabase.rpc("current_profile_role");
110	    if (!can(role as Role, "source")) {
111	      return NextResponse.json({ ok: false, reason: "Insufficient permissions." }, { status: 403 });
112	    }
113	  } else if (demoLoginEnabled) {
114	    // Same open-demo cost gate as /api/hermes/chat: env-resident provider keys
115	    // are spendable only by a caller holding a valid demo session.
116	    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
117	      return NextResponse.json({ ok: false, reason: "Sign in to use the sourcing agent." }, { status: 401 });
118	    }
119	  }
120	
121	  const rl = checkRateLimit(rateLimitKey(req, "sourcing-agent", userId), { windowMs: 60_000, max: 10 });
122	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
123	
124	  const validated = await validateBody(req, SourcingAgentSchema, { maxBytes: 200_000 });
125	  if (!validated.ok) return validated.response;
126	  const { count = 5, provider, apiKeyId, model } = validated.data;
127	  const campaign = validated.data.campaign as unknown as Campaign;
128	  const existing = validated.data.existing as unknown as Candidate[];
129	  const weights: ScoringWeights = campaign?.scoringWeights;
130	
131	  if (!campaign?.jobAnalysis || !weights) {
132	    return NextResponse.json({ ok: false, reason: "Malformed campaign payload." }, { status: 400 });
133	  }
134	
135	  const slug = provider as AiProviderSlug;
136	  const vaultKey = await resolveVaultSecret(apiKeyId);
137	  const key = vaultKey || process.env[PROVIDER_ENV[slug]] || "";
138	  if (!key) {
139	    return NextResponse.json({ ok: false, reason: `No API key configured for ${provider}.` });
140	  }
141	
142	  const githubToken = process.env.GITHUB_TOKEN ?? "";
143	  const tavilyKey = supabase ? await resolveStoredTavilyKey(supabase) : null;
144	  const runner = makeSourcingToolRunner(campaign, existing, weights, githubToken, tavilyKey ?? undefined);
145	  const servers: ResolvedMcpServer[] = [
146	    { url: "builtin:sourcing-agent", token: "", tools: SOURCING_TOOL_DEFS, run: runner.run },
147	  ];
148	
149	  const toolModel = model || DEFAULT_MODEL[slug];
150	  const prompt = buildPrompt(campaign, count);
151	  const result =
152	    slug === "anthropic"
153	      ? await runAnthropicWithTools({ model: toolModel, system: SYSTEM_PROMPT, prompt, key, servers, maxRounds: 6 })
154	      : await runOpenAiWithTools({ provider: slug, model: toolModel, system: SYSTEM_PROMPT, prompt, key, servers, maxRounds: 6 });
155	
156	  const foundCandidates = runner.getFound();
157	  if (!result.ok) {
158	    // Even on a loop failure, return whatever real candidates were actually
159	    // found before it failed — the search itself is real and useful even
160	    // without a draft, same "don't throw away real work" posture as the rest
161	    // of this app's real-sourcing paths.
162	    return NextResponse.json({
163	      ok: foundCandidates.length > 0,
164	      reason: result.reason ?? "Agent loop failed.",
165	      candidates: foundCandidates.map((c) => ({ ...c, matchScore: c.matchScore })),
166	    });
167	  }
168	
169	  const drafts = parseDrafts(result.text ?? "");
170	  const byId = new Map(foundCandidates.map((c) => [c.id, c]));
171	  // Only ever attach a draft to a candidate the tool loop actually surfaced —
172	  // never trust a candidateId the model invented that wasn't in a real result.
173	  const candidates = drafts
174	    .map((d) => {
175	      const cand = byId.get(d.candidateId);
176	      if (!cand) return null;
177	      return { ...cand, draftSubject: d.subject, draftBody: d.body };
178	    })
179	    .filter((c): c is Candidate & { draftSubject: string; draftBody: string } => c !== null);
180	
181	  return NextResponse.json({ ok: true, candidates, totalFound: foundCandidates.length });
182	}

