 99	function logUpstream(level: "info" | "error", message: string, meta?: Record<string, unknown>) {
100	  // Structured log line for production observability. In Vercel this becomes
101	  // a regular function log; in self-hosted environments it can be scraped.
102	  // Redact before emitting: mask sensitive-keyed values, then scrub any emails /
103	  // credentials that leaked into free-text fields (e.g. upstream error bodies,
104	  // network error messages) so nothing sensitive reaches a log sink.
105	  const entry = { time: new Date().toISOString(), source: "hermes-proxy", level, message, ...redactObject(meta ?? {}) };
106	  const line = redactSecrets(redactEmail(JSON.stringify(entry)));
107	  if (level === "error") {
108	    console.error(line);
109	  } else {
110	    console.log(line);
111	  }
112	}
