119	/**
120	 * Resolve the caller's enabled MCP servers into connectable servers with their tools.
121	 * The bearer token for each is resolved from the vault server-side (never from the
122	 * browser). http(s) only (SSRF). Servers that fail to connect or expose no tools are
123	 * skipped, so a broken server can't block the chat.
124	 */
125	async function gatherMcpServers(
126	  servers: { url: string; apiKeyId?: string }[],
127	): Promise<ResolvedMcpServer[]> {
128	  const resolved: ResolvedMcpServer[] = [];
129	  for (const s of servers) {
130	    let parsed: URL;
131	    try {
132	      parsed = new URL(s.url);
133	    } catch {
134	      continue;
135	    }
136	    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") continue;
137	    // SSRF guard: block private/loopback/link-local/metadata hosts (and DNS-rebinding)
138	    // before the server ever dials the caller-supplied URL. This server is reused for
139	    // every tool call the model makes during the loop, so this is a repeatable channel
140	    // — not just a one-shot probe.
141	    const guard = await assertPublicUrl(s.url);
142	    if (!guard.ok) continue;
143	    const token = s.apiKeyId ? await resolveVaultSecret(s.apiKeyId) : "";
144	    const conn = await connectAndListTools(s.url, token);
145	    if (conn.ok && conn.tools && conn.tools.length) {
146	      resolved.push({ url: s.url, token, tools: conn.tools });
147	    }
148	  }
149	  return resolved;
150	}
