 48	async function requireOperator(req: NextRequest) {
 49	  const prodBlock = prodFailClosed();
 50	  if (prodBlock) return { response: prodBlock } as const;
 51	  if (!supabaseEnabled) {
 52	    return {
 53	      response: NextResponse.json({ ok: true, demo: true, specs: [] }),
 54	    } as const;
 55	  }
 56	  const supabase = await getServerSupabase();
 57	  if (!supabase) return { response: NextResponse.json({ ok: false, reason: "No Supabase client." }, { status: 500 }) } as const;
 58	  const {
 59	    data: { user },
 60	  } = await supabase.auth.getUser();
 61	  if (!user) return { response: NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 }) } as const;
 62	  const { data: role } = await supabase.rpc("current_profile_role");
 63	  if (!can(role as Role, "source")) {
 64	    return { response: NextResponse.json({ ok: false, reason: "Insufficient permissions." }, { status: 403 }) } as const;
 65	  }
 66	  const { data: wid } = await supabase.rpc("current_workspace_id");
 67	  return { supabase, user, workspaceId: wid as string } as const;
 68	}
