 70	export async function GET(req: NextRequest) {
 71	  const auth = await requireOperator(req);
 72	  if ("response" in auth) return auth.response;
 73	  const { data, error } = await auth.supabase
 74	    .from("agent_specs")
 75	    .select("id, name, role_brief, channels, guardrails, seat_id, flowise_chatflow_id, status, created_at")
 76	    .neq("status", "archived")
 77	    .order("created_at", { ascending: false });
 78	  if (error) return NextResponse.json({ ok: false, reason: "Failed to load agents." }, { status: 500 });
 79	  return NextResponse.json({ ok: true, specs: data ?? [] });
 80	}
