 82	export async function POST(req: NextRequest) {
 83	  const rl = checkRateLimit(rateLimitKey(req, "agent-specs"), { windowMs: 60_000, max: 20 });
 84	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
 85	  const auth = await requireOperator(req);
 86	  if ("response" in auth) return auth.response;
 87	  const validated = await validateBody(req, CreateSpecSchema, { maxBytes: 50_000 });
 88	  if (!validated.ok) return validated.response;
 89	  const { data, error } = await auth.supabase
 90	    .from("agent_specs")
 91	    .insert({ ...validated.data, workspace_id: auth.workspaceId, owner_id: auth.user.id })
 92	    .select("id")
 93	    .maybeSingle();
 94	  if (error || !data) return NextResponse.json({ ok: false, reason: "Failed to create agent." }, { status: 500 });
 95	  return NextResponse.json({ ok: true, id: data.id });
 96	}
