 98	export async function PATCH(req: NextRequest) {
 99	  const rl = checkRateLimit(rateLimitKey(req, "agent-specs"), { windowMs: 60_000, max: 30 });
100	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
101	  const auth = await requireOperator(req);
102	  if ("response" in auth) return auth.response;
103	  const validated = await validateBody(req, UpdateSpecSchema, { maxBytes: 50_000 });
104	  if (!validated.ok) return validated.response;
105	  const { id, ...updates } = validated.data;
106	  const { error } = await auth.supabase
107	    .from("agent_specs")
108	    .update({ ...updates, updated_at: new Date().toISOString() })
109	    .eq("id", id);
110	  if (error) return NextResponse.json({ ok: false, reason: "Failed to update agent." }, { status: 500 });
111	  return NextResponse.json({ ok: true });
