 66	function asRecord(value: unknown): UnknownRecord | null {
 67	  return typeof value === "object" && value !== null && !Array.isArray(value) ? (value as UnknownRecord) : null;
 68	}
 69	
 70	function text(value: unknown, max: number): string | null {
 71	  if (typeof value !== "string") return null;
 72	  const normalized = value.trim();
 73	  return normalized.length > 0 && normalized.length <= max ? normalized : null;
 74	}
 75	
 76	function textList(value: unknown, maxItems: number, maxLength: number): string[] {
 77	  if (!Array.isArray(value)) return [];
 78	  const result: string[] = [];
 79	  for (const item of value) {
 80	    const normalized = text(item, maxLength);
 81	    if (normalized && !result.includes(normalized)) result.push(normalized);
 82	    if (result.length >= maxItems) break;
 83	  }
 84	  return result;
 85	}
 86	
 87	function publicScreeningQuestions(value: unknown): string[] {
 88	  return textList(value, 5, 500);
