147	function normalizedPhone(value: string, phoneCountry?: string): string | null {
148	  let digits = value.replace(/\D/g, "");
149	  const countryDigits = (phoneCountry ?? "").replace(/\D/g, "");
150	  // The public form prefixes a national number with its selected country code.
151	  // Strip one optional national trunk zero so `+33 06…` becomes E.164 `+336…`.
152	  if (countryDigits && digits.startsWith(countryDigits)) {
153	    const national = digits.slice(countryDigits.length);
154	    if (national.length >= 7 && national.startsWith("0")) digits = `${countryDigits}${national.slice(1)}`;
155	  }
156	  return digits.length >= 6 && digits.length <= 16 ? `+${digits}` : null;
157	}
