178	function canonicalAnswers(input: PublicCareerApplicationInput, job: PublicCareerJob | null): ChatboxScreeningAnswer[] | null {
179	  const questions = canonicalScreeningQuestions(job);
180	  const answers: ChatboxScreeningAnswer[] = [];
181	  const mobility = answerFor(input.answers, "mobility");
182	  const visa = answerFor(input.answers, "visa");
183	  const keyExp = answerFor(input.answers, "keyexp");
184	  const toolExp = answerFor(input.answers, "toolexp");
185	  const project = answerFor(input.answers, "project");
186	
187	  if (input.path === "A") {
188	    if (!mobility || !visa || !keyExp || !toolExp || !project) return null;
189	    const mobilityAnswer = mobility.answer;
190	    const visaAnswer = visa.answer;
191	    const projectAnswer = project.answer;
192	    if (
193	      (mobilityAnswer !== "Yes" && mobilityAnswer !== "No" && mobilityAnswer !== "Relocation required") ||
194	      (visaAnswer !== "Yes" && visaAnswer !== "No") ||
195	      (projectAnswer !== "Yes" && projectAnswer !== "No") ||
196	      !Number.isInteger(keyExp.stars) ||
197	      !Number.isInteger(toolExp.stars) ||
198	      keyExp.stars! < 1 ||
199	      keyExp.stars! > 5 ||
200	      toolExp.stars! < 1 ||
201	      toolExp.stars! > 5
202	    ) {
203	      return null;
204	    }
205	    answers.push(
206	      { question: questions[0]!, answer: mobilityAnswer, kind: "mobility" },
207	      { question: questions[1]!, answer: visaAnswer, kind: "visa" },
208	      { question: questions[2]!, answer: `${keyExp.stars}/5`, kind: "keyexp", stars: keyExp.stars },
209	      { question: questions[3]!, answer: `${toolExp.stars}/5`, kind: "toolexp", stars: toolExp.stars },
210	      { question: questions[4]!, answer: projectAnswer, kind: "project" },
211	    );
212	  }
213	
214	  for (const raw of input.answers) {
215	    if (raw.kind !== "quickmatch") continue;
216	    const question = text(raw.question, 80);
217	    const answer = text(raw.answer, 160);
218	    if (question && answer && QUICK_MATCH_QUESTIONS.has(question)) {
219	      answers.push({ question, answer, kind: "quickmatch" });
220	    }
221	  }
222	  return answers;
223	}
