225	function compactContactPref(value: PublicCareerApplicationInput["contactPref"]): ChatboxSubmission["contactPref"] | undefined {
226	  const time = text(value?.time, 40);
227	  const day = text(value?.day, 40);
228	  return time || day ? { ...(time ? { time } : {}), ...(day ? { day } : {}) } : undefined;
