231	/**
232	 * Rebuild a durable submission from bounded public input. Client-supplied role
233	 * titles, scores, ratings, identifiers, and status are never trusted.
234	 */
235	export function buildPublicCareerSubmission(
236	  input: PublicCareerApplicationInput,
237	  jobs: PublicCareerJob[],
238	  createdAt = new Date().toISOString(),
239	): ChatboxSubmission | null {
240	  if (input.path !== "A" && input.path !== "B") return null;
241	  const job = input.campaignId ? jobs.find((candidate) => candidate.id === input.campaignId) ?? null : null;
242	  if (input.campaignId && !job) return null;
243	  // Path A is an application to an explicit public campaign, never an
244	  // arbitrary client-supplied role. Path B remains the talent-pool route and
245	  // may use a candidate-described role when no public campaign is selected.
246	  if (input.path === "A" && !job) return null;
247	
248	  const firstName = text(input.firstName, 80);
249	  const lastName = text(input.lastName, 80);
250	  const email = normalizedEmail(input.email);
251	  const phone = normalizedPhone(input.phone, text(input.detected.phoneCountry, 16) ?? undefined);
252	  const roleTitle = job?.title ?? text(input.roleTitle, 160);
253	  const answers = canonicalAnswers(input, job);
254	  if (!firstName || !lastName || !email || !phone || !roleTitle || !answers) return null;
255	
256	  const mobility = answerFor(input.answers, "mobility")?.answer;
257	  const visa = answerFor(input.answers, "visa")?.answer;
258	  const keyExpStars = answerFor(input.answers, "keyexp")?.stars;
259	  const toolStars = answerFor(input.answers, "toolexp")?.stars;
260	  const project = answerFor(input.answers, "project")?.answer;
261	  const score = computeChatboxScore({
262	    mobility: mobility === "Yes" || mobility === "No" || mobility === "Relocation required" ? mobility : undefined,
263	    needsVisa: visa === "Yes" ? true : visa === "No" ? false : undefined,
264	    keyExpStars,
265	    toolStars,
266	    projectYes: project === "Yes" ? true : project === "No" ? false : undefined,
267	    hasContactPref: Boolean(compactContactPref(input.contactPref)),
268	  });
269	
270	  return {
271	    id: `cbx_${crypto.randomUUID()}`,
272	    path: input.path,
273	    campaignId: job?.id ?? null,
274	    roleTitle,
275	    firstName,
276	    lastName,
277	    email,
278	    phone,
279	    ...(text(input.cvFileName, 180) ? { cvFileName: text(input.cvFileName, 180)! } : {}),
280	    detected: normalizedDetected(input.detected),
281	    answers,
282	    score,
283	    starRating: deriveStarRating(score.total, DEFAULT_STAR_THRESHOLDS),
284	    ...(compactContactPref(input.contactPref) ? { contactPref: compactContactPref(input.contactPref) } : {}),
285	    status: "new",
286	    createdAt,
287	  };
288	}

