211	function matchCampaigns(d: Draft, open: PublicCareerJob[]): PublicCareerJob[] {
212	  const terms = [d.qm.desired, d.qm.sector, d.qm.city, ...(d.detected.skills ?? [])]
213	    .filter(Boolean)
214	    .join(" ")
215	    .toLowerCase();
216	  const tokens = terms.split(/[^a-z0-9]+/).filter((t) => t.length > 2);
217	  if (!tokens.length) return [];
218	  const scored = open
219	    .map((c) => {
220	      const hay = [
221	        c.title,
222	        c.department,
223	        ...c.requiredSkills,
224	        ...c.niceToHaveSkills,
225	        ...c.industryExperience,
226	      ]
227	        .join(" ")
228	        .toLowerCase();
229	      let score = 0;
230	      for (const t of tokens) if (hay.includes(t)) score += 1;
231	      return { c, score };
232	    })
233	    .filter((x) => x.score > 0)
234	    .sort((a, b) => b.score - a.score);
235	  return scored.slice(0, 5).map((x) => x.c);
