 18	/**
 19	 * On-demand sourcing agent run — the deer-flow-style graph
 20	 * (planner → sourcer → screener → outreach → reporter) over the same real
 21	 * search + deterministic scoring the single-shot /api/sourcing-agent uses.
 22	 *
 23	 * Same posture as that route: TEXT + SEARCH ONLY — this never sends anything;
 24	 * gate-passing drafts still require the human approval gate (or gated
 25	 * autopilot's system approval) before /api/outreach/send will touch the wire.
 26	 *
 27	 * With Supabase configured, every node persists to agent_runs (resumable) and
 28	 * narrates to agent_events (append-only, no send path). In demo mode the run
 29	 * executes statelessly and just returns its result.
 30	 */
 31	const AGENT_PROVIDERS = ["anthropic", "openai", "groq", "xai", "mistral"] as const;
 32	
 33	const AgentRunSchema = z.object({
 34	  campaign: z.record(z.string(), z.unknown()),
 35	  existing: z.array(z.record(z.string(), z.unknown())).max(500).default([]),
 36	  count: z.number().int().min(1).max(8).default(5),
 37	  provider: z.enum(AGENT_PROVIDERS),
 38	  apiKeyId: z.string().uuid().optional(),
 39	  model: z.string().regex(/^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$/).optional(),
 40	  specId: z.string().uuid().optional(),
 41	});
 42	
 43	export async function POST(req: NextRequest) {
 44	  const prodBlock = prodFailClosed();
 45	  if (prodBlock) return prodBlock;
 46	
 47	  const supabase = supabaseEnabled ? await getServerSupabase() : null;
 48	  let workspaceId: string | null = null;
 49	  let userId: string | null = null;
 50	  if (supabaseEnabled) {
 51	    if (!supabase) return NextResponse.json({ ok: false, reason: "No Supabase client." }, { status: 500 });
 52	    const {
 53	      data: { user },
 54	    } = await supabase.auth.getUser();
 55	    if (!user) return NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 });
 56	    userId = user.id;
 57	    const { data: role } = await supabase.rpc("current_profile_role");
 58	    if (!can(role as Role, "source")) {
 59	      return NextResponse.json({ ok: false, reason: "Insufficient permissions." }, { status: 403 });
 60	    }
 61	    const { data: wid } = await supabase.rpc("current_workspace_id");
 62	    workspaceId = (wid as string) ?? null;
 63	  } else if (demoLoginEnabled) {
 64	    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
 65	      return NextResponse.json({ ok: false, reason: "Sign in to run agents." }, { status: 401 });
 66	    }
 67	  }
 68	
 69	  const rl = checkRateLimit(rateLimitKey(req, "agents-run", userId), { windowMs: 60_000, max: 6 });
 70	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
 71	
 72	  const validated = await validateBody(req, AgentRunSchema, { maxBytes: 200_000 });
 73	  if (!validated.ok) return validated.response;
 74	  const { count = 5, provider, apiKeyId, model, specId } = validated.data;
 75	  const campaign = validated.data.campaign as unknown as Campaign;
 76	  const existing = validated.data.existing as unknown as Candidate[];
 77	  const weights: ScoringWeights = campaign?.scoringWeights;
 78	  if (!campaign?.jobAnalysis || !weights) {
 79	    return NextResponse.json({ ok: false, reason: "Malformed campaign payload." }, { status: 400 });
 80	  }
 81	
 82	  const slug = provider as AiProviderSlug;
 83	  const vaultKey = await resolveVaultSecret(apiKeyId);
 84	  const key = vaultKey || process.env[PROVIDER_ENV[slug]] || "";
 85	  if (!key) return NextResponse.json({ ok: false, reason: `No API key configured for ${provider}.` });
 86	  const llmModel = model || DEFAULT_MODEL[slug];
 87	
 88	  const tavilyKey = supabase ? await resolveStoredTavilyKey(supabase) : null;
 89	  const runner = makeSourcingToolRunner(campaign, existing, weights, process.env.GITHUB_TOKEN ?? "", tavilyKey ?? undefined);
 90	  const deps: GraphDeps = {
 91	    async generate(system, prompt) {
 92	      const reqSpec = buildCloudRequest(slug, llmModel, system, prompt, key, 1024);
 93	      const res = await fetch(reqSpec.url, {
 94	        method: "POST",
 95	        headers: reqSpec.headers,
 96	        body: reqSpec.body,
 97	        signal: AbortSignal.timeout(45_000),
 98	      });
 99	      if (!res.ok) throw new Error(`${provider} ${res.status}`);
100	      return parseCloudResponse(slug, await res.json());
101	    },
102	    async search(platform, query, searchCount) {
103	      const before = runner.getFound().length;
104	      await runner.run("search_candidates", { platform, query, count: searchCount });
105	      return runner
106	        .getFound()
107	        .slice(before)
108	        .map((c) => ({
109	          id: c.id,
110	          name: c.name,
111	          matchScore: c.matchScore,
112	          currentTitle: c.currentTitle,
113	          currentCompany: c.currentCompany,
114	        })) as CandidateLite[];
115	    },
116	  };
117	
118	  // Persistent run row (when the backend exists) — resumable + auditable.
119	  let runId: string | null = null;
120	  if (supabase && workspaceId) {
121	    const { data: run } = await supabase
122	      .from("agent_runs")
123	      .insert({ spec_id: specId ?? null, workspace_id: workspaceId, state_json: {}, node: "planner" })
124	      .select("id")
125	      .maybeSingle();
126	    runId = run?.id ?? null;
127	  }
128	
129	  const state = initialState(campaign.jobAnalysis as unknown as Record<string, unknown>, count);
130	  const result = await runGraph(state, deps, async (node, s, event) => {
131	    if (!supabase || !workspaceId || !runId) return;
132	    await supabase
133	      .from("agent_runs")
134	      .update({
135	        node,
136	        state_json: s as unknown as Record<string, unknown>,
137	        step_count: s.drafts.length + s.planCursor,
138	        status: node === "done" ? "done" : "running",
139	        ...(node === "done" ? { finished_at: new Date().toISOString() } : {}),
140	      })
141	      .eq("id", runId);
142	    await supabase
143	      .from("agent_events")
144	      .insert({ run_id: runId, workspace_id: workspaceId, type: event.type, payload: event.payload });
145	  });
146	
147	  const found = runner.getFound();
148	  const byId = new Map(found.map((c) => [c.id, c]));
149	  const candidates = result.state.drafts
150	    .filter((d) => d.gatePassed)
151	    .map((d) => {
152	      const cand = byId.get(d.candidateId);
153	      return cand ? { ...cand, draftSubject: d.subject, draftBody: d.body } : null;
154	    })
155	    .filter((c): c is Candidate & { draftSubject: string; draftBody: string } => c !== null);
156	
157	  return NextResponse.json({
158	    ok: true,
159	    runId,
160	    report: result.state.report ?? "",
161	    candidates,
162	    totalFound: found.length,
163	    heldByGate: result.state.drafts.filter((d) => !d.gatePassed).length,
164	    errors: result.state.errors,
165	  });
166	}

