1211	export interface ReplyClassification {
1212	  intent: ReplyIntent;
1213	  confidence: number;
1214	  reasoning: string;
1215	  suggestedAction: string;
1216	  draftResponse: string;
1217	}
1218	
1219	export function classifyReply(replyText: string, candidateName = "there"): ReplyClassification {
1220	  const t = replyText.toLowerCase();
1221	  const first = candidateName.split(" ")[0];
1222	  let intent: ReplyIntent = "UNCLEAR";
1223	  let confidence = 0.6;
1224	  let reasoning = "No strong signal detected; routing to human review.";
1225	
1226	  // Multilingual intent detection (EN/FR/ES/DE/PT/IT/NL via the merged lexicon).
1227	  if (REPLY_LEXICON.negative.test(t)) {
1228	    intent = "NEGATIVE";
1229	    confidence = 0.93;
1230	    reasoning = "Opt-out / hostile language detected: must stop immediately and escalate.";
1231	  } else if (REPLY_LEXICON.ooo.test(t)) {
1232	    intent = "OOO";
1233	    confidence = 0.95;
1234	    reasoning = "Auto-reply / absence language detected.";
1235	  } else if (REPLY_LEXICON.notInterested.test(t)) {
1236	    intent = "NOT_INTERESTED";
1237	    confidence = 0.9;
1238	    reasoning = "Explicit decline language detected.";
1239	  } else if (REPLY_LEXICON.referral.test(t)) {
1240	    intent = "REFERRAL";
1241	    confidence = 0.82;
1242	    reasoning = "Candidate is pointing to someone else (referral path).";
1243	  } else if (REPLY_LEXICON.interested.test(t)) {
1244	    if (REPLY_LEXICON.qualified.test(t)) {
1245	      intent = "QUALIFIED_INTEREST";
1246	      confidence = 0.78;
1247	      reasoning = "Positive signal with open questions: answer, then offer the calendar.";
1248	    } else {
1249	      intent = "INTERESTED";
1250	      confidence = 0.9;
1251	      reasoning = "Clear positive intent with a request to proceed.";
1252	    }
1253	  } else if (/(maybe|perhaps|not sure|depends|tell me more|what.s the role|peut-être|quizás|vielleicht)/i.test(t)) {
1254	    intent = "QUALIFIED_INTEREST";
1255	    confidence = 0.72;
1256	    reasoning = "Soft positive with hesitation: nurture and inform.";
1257	  } else if (REPLY_LEXICON.qualified.test(t)) {
1258	    // Role/comp questions with no decline → qualified interest (per reply_classification_skill).
1259	    intent = "QUALIFIED_INTEREST";
1260	    confidence = 0.72;
1261	    reasoning = "Questions about comp/role without a decline: answer and append the calendar.";
1262	  }
1263	
1264	  return {
1265	    intent,
1266	    confidence,
1267	    reasoning,
1268	    suggestedAction: SUGGESTED_ACTION[intent],
1269	    draftResponse: humanizeText(draftFor(intent, first)),
1270	  };
1271	}
1272	
1273	const SUGGESTED_ACTION: Record<ReplyIntent, string> = {
1274	  INTERESTED: "Send booking link immediately (15-min SLA) and update stage to Interested.",
1275	  QUALIFIED_INTEREST: "Answer their questions, append the calendar link, keep nurturing.",
1276	  NOT_INTERESTED: "Send a gracious close and start the suppression timer.",
1277	  REFERRAL: "Thank them and create the referred candidate as a new lead.",
1278	  OOO: "Pause the sequence until their return date.",
1279	  UNCLEAR: "Queue for human review: intent ambiguous.",
1280	  NEGATIVE: "Stop all outreach immediately, add to do-not-contact, and escalate.",
1281	};
1282	
1283	function draftFor(intent: ReplyIntent, first: string): string {
1284	  switch (intent) {
1285	    case "INTERESTED":
1286	      return `Brilliant, ${first}! Thank you. Here's my calendar so you can grab whatever suits: {{cal_link}}. I'll send a Teams invite the moment you pick a slot. Looking forward to it.`;
1287	    case "QUALIFIED_INTEREST":
1288	      return `Great questions, ${first}. Quick answers: comp and remote policy are both flexible within band, and the team is small and senior. If it's easier to talk it through, here's my calendar: {{cal_link}}.`;
1289	    case "NOT_INTERESTED":
1290	      return `Completely understand, ${first}. Thanks for the quick reply. I'll close this out and won't keep nudging. If the timing ever changes, you know where to find me. All the best.`;
1291	    case "REFERRAL":
1292	      return `Really appreciate that, ${first}! If you can intro me, I'd be glad to reach out. Thank you for thinking of the right person.`;
1293	    case "OOO":
1294	      return `Thanks for the note. Enjoy the time away, ${first}. I'll pause and circle back after you're settled back in.`;
1295	    case "NEGATIVE":
1296	      return `Understood, ${first}. I've removed you from all outreach and you won't hear from us again. Apologies for the intrusion.`;
1297	    default:
1298	      return `Thanks, ${first}. Just to make sure I read you right: would you like me to share more on the role, or is now not the moment?`;
1299	  }
1300	}
