  1	/* ============================================================================
  2	   SOURCING AGENT GRAPH — deer-flow's planner/worker/reporter pattern, ported
  3	   to a plain TypeScript state machine (deliberately NOT LangGraph: state is a
  4	   JSON row in agent_runs, so a serverless timeout is a resume, not a failure).
  5	
  6	   planner → sourcer → screener → outreach → reporter → done
  7	
  8	   Each node executes exactly one step: it receives the state, returns the
  9	   updated state plus the next node. The driver (API route) persists after
 10	   every step. All side-effectful dependencies (LLM, platform search) are
 11	   injected, so the whole graph is unit-testable with mocks.
 12	
 13	   Guardrails inherited from the platform:
 14	   - The sourcer only reports candidates the injected search actually returned
 15	     (the runner accumulates real results — the model never invents people).
 16	   - Every outreach draft passes gateOutbound(); failing drafts are kept as
 17	     'blocked' for human review, never silently dropped or sent.
 18	   - step_count is bounded by MAX_STEPS — a runaway plan halts as 'failed'.
 19	   ========================================================================== */
 20	
 21	import { z } from "zod";
 22	import { gateOutbound } from "@/lib/gate";
 23	
 24	export type AgentNode = "planner" | "sourcer" | "screener" | "outreach" | "reporter" | "done";
 25	
 26	export const MAX_STEPS = 24;
 27	export const DEFAULT_MIN_SCORE = 70; // mirrors MIN_SCORE_FLOOR in rules.ts
 28	
 29	// ---------------------------------------------------------------------------
 30	// Plan schema — same shape deer-flow validates server-side, minus locales.
 31	// ---------------------------------------------------------------------------
 32	export const PlanStepSchema = z.object({
 33	  title: z.string().min(1).max(200),
 34	  platform: z.enum(["GitHub", "LinkedIn", "Stack Overflow", "Dribbble", "Behance"]),
 35	  query: z.string().min(2).max(256),
 36	});
 37	export const PlanSchema = z.object({
 38	  thought: z.string().max(2_000).default(""),
 39	  steps: z.array(PlanStepSchema).min(1).max(6),
 40	});
 41	export type Plan = z.infer<typeof PlanSchema>;
 42	
 43	export interface CandidateLite {
 44	  id: string;
 45	  name: string;
 46	  matchScore: number;
 47	  currentTitle?: string;
 48	  currentCompany?: string;
 49	}
 50	
 51	export interface DraftLite {
 52	  candidateId: string;
 53	  subject: string;
 54	  body: string;
 55	  gatePassed: boolean;
 56	  gateReasons?: string[];
 57	}
 58	
 59	export interface AgentGraphState {
 60	  /** Role brief (Campaign.jobAnalysis shape), set at run creation. */
 61	  brief: Record<string, unknown>;
 62	  draftCount: number;
 63	  minScore: number;
 64	  plan?: Plan;
 65	  /** Next plan step the sourcer should execute (one per graph step — resumable). */
 66	  planCursor: number;
 67	  candidates: CandidateLite[];
 68	  screened: CandidateLite[];
 69	  drafts: DraftLite[];
 70	  report?: string;
 71	  errors: string[];
 72	}
 73	
 74	export function initialState(brief: Record<string, unknown>, draftCount = 5, minScore = DEFAULT_MIN_SCORE): AgentGraphState {
 75	  return { brief, draftCount, minScore, planCursor: 0, candidates: [], screened: [], drafts: [], errors: [] };
 76	}
 77	
 78	export interface GraphDeps {
 79	  /** Single LLM completion. */
 80	  generate(system: string, prompt: string): Promise<string>;
 81	  /** Real platform search; returns only real, already-scored candidates. */
 82	  search(platform: string, query: string, count: number): Promise<CandidateLite[]>;
 83	}
 84	
 85	/** Tolerant JSON extraction — models fence and preface JSON. Same posture as
 86	 *  parseDrafts in /api/sourcing-agent. */
 87	export function extractJson(text: string): unknown {
 88	  const match = (text ?? "").match(/\{[\s\S]*\}/);
 89	  if (!match) return null;
 90	  try {
 91	    return JSON.parse(match[0]);
 92	  } catch {
 93	    return null;
 94	  }
 95	}
 96	
 97	const PLANNER_SYSTEM =
 98	  "You plan candidate sourcing for one role. Given the role brief, output ONLY JSON " +
 99	  '(no prose, no fences): {"thought": "<one line>", "steps": [{"title": "...", ' +
100	  '"platform": "GitHub"|"LinkedIn"|"Stack Overflow"|"Dribbble"|"Behance", "query": "<search query>"}]}. ' +
101	  "1-6 steps. Pick only platforms that genuinely fit the role (no Dribbble for backend). " +
102	  "Queries are what a senior sourcer would type into that platform's search.";
103	
104	const OUTREACH_SYSTEM =
105	  "You draft one first-touch outreach message from a recruiter to a candidate. Output ONLY JSON " +
106	  '(no prose, no fences): {"subject": "<under 60 chars>", "body": "<under 120 words>"}. ' +
107	  "Lead with their specific real work, one genuine reason for reaching out, soft low-pressure ask. " +
108	  "No AI slop, no corporate filler, no em-dashes, never mention tools or automation.";
109	
110	export interface StepResult {
111	  node: AgentNode;
112	  state: AgentGraphState;
113	  /** Narration for agent_events — never a message, never sendable. */
114	  event: { type: string; payload: Record<string, unknown> };
115	}
116	
117	/** Execute exactly one node. The driver persists state after every call. */
118	export async function stepGraph(node: AgentNode, state: AgentGraphState, deps: GraphDeps): Promise<StepResult> {
119	  switch (node) {
120	    case "planner": {
121	      const raw = await deps.generate(PLANNER_SYSTEM, `Role brief:\n${JSON.stringify(state.brief).slice(0, 4_000)}`);
122	      const parsed = PlanSchema.safeParse(extractJson(raw));
123	      if (!parsed.success) {
124	        const errors = [...state.errors, "planner: invalid plan JSON"];
125	        return { node: "done", state: { ...state, errors }, event: { type: "plan_failed", payload: {} } };
126	      }
127	      return {
128	        node: "sourcer",
129	        state: { ...state, plan: parsed.data, planCursor: 0 },
130	        event: { type: "plan_ready", payload: { steps: parsed.data.steps.length } },
131	      };
132	    }
133	
134	    case "sourcer": {
135	      const step = state.plan?.steps[state.planCursor];
136	      if (!step) return { node: "screener", state, event: { type: "sourcing_complete", payload: { found: state.candidates.length } } };
137	      let found: CandidateLite[] = [];
138	      let errors = state.errors;
139	      try {
140	        found = await deps.search(step.platform, step.query, 8);
141	      } catch (err) {
142	        errors = [...errors, `sourcer(${step.platform}): ${err instanceof Error ? err.message : "search failed"}`];
143	      }
144	      const seen = new Set(state.candidates.map((c) => c.id));
145	      const fresh = found.filter((c) => !seen.has(c.id));
146	      const next = state.planCursor + 1;
147	      return {
148	        node: next < (state.plan?.steps.length ?? 0) ? "sourcer" : "screener",
149	        state: { ...state, candidates: [...state.candidates, ...fresh], planCursor: next, errors },
150	        event: { type: "search_step", payload: { platform: step.platform, found: fresh.length } },
151	      };
152	    }
153	
154	    case "screener": {
155	      const screened = [...state.candidates]
156	        .filter((c) => c.matchScore >= state.minScore)
157	        .sort((a, b) => b.matchScore - a.matchScore)
158	        .slice(0, state.draftCount);
159	      const next: AgentNode = screened.length > 0 ? "outreach" : "reporter";
160	      return {
161	        node: next,
162	        state: { ...state, screened },
163	        event: { type: "screened", payload: { kept: screened.length, of: state.candidates.length } },
164	      };
165	    }
166	
167	    case "outreach": {
168	      // One draft per step — keeps each serverless invocation short and the
169	      // run resumable mid-outreach.
170	      const target = state.screened[state.drafts.length];
171	      if (!target) return { node: "reporter", state, event: { type: "outreach_complete", payload: { drafts: state.drafts.length } } };
172	      const raw = await deps.generate(
173	        OUTREACH_SYSTEM,
174	        `Role brief:\n${JSON.stringify(state.brief).slice(0, 2_000)}\n\nCandidate:\n${JSON.stringify(target)}`,
175	      );
176	      const parsed = extractJson(raw) as { subject?: string; body?: string } | null;
177	      const subject = String(parsed?.subject ?? "").slice(0, 255);
178	      const body = String(parsed?.body ?? "").slice(0, 5_000);
179	      const gate = body ? gateOutbound(body) : { pass: false as const, reasons: ["empty-draft"], text: "" };
180	      const draft: DraftLite = gate.pass
181	        ? { candidateId: target.id, subject, body: gate.text, gatePassed: true }
182	        : { candidateId: target.id, subject, body, gatePassed: false, gateReasons: gate.reasons };
183	      const drafts = [...state.drafts, draft];
184	      return {
185	        node: drafts.length < state.screened.length ? "outreach" : "reporter",
186	        state: { ...state, drafts },
187	        event: { type: "draft", payload: { candidateId: target.id, gatePassed: gate.pass } },
188	      };
189	    }
190	
191	    case "reporter": {
192	      // Deterministic — a report is bookkeeping, not creativity.
193	      const passed = state.drafts.filter((d) => d.gatePassed).length;
194	      const report =
195	        `Sourced ${state.candidates.length} real candidates across ${state.plan?.steps.length ?? 0} searches; ` +
196	        `${state.screened.length} passed screening (score >= ${state.minScore}); ` +
197	        `${passed} drafts ready for approval, ${state.drafts.length - passed} held by the gate` +
198	        (state.errors.length ? `; ${state.errors.length} step error(s).` : ".");
199	      return { node: "done", state: { ...state, report }, event: { type: "report", payload: { passed } } };
200	    }
201	
202	    case "done":
203	      return { node: "done", state, event: { type: "noop", payload: {} } };
204	  }
205	}
206	
207	/** Drive the graph to completion (or the step budget). Used by the API route
208	 *  and tests; the route persists via onStep after every node. */
209	export async function runGraph(
210	  state: AgentGraphState,
211	  deps: GraphDeps,
212	  onStep?: (node: AgentNode, state: AgentGraphState, event: StepResult["event"]) => Promise<void>,
213	  startNode: AgentNode = "planner",
214	  startStep = 0,
215	): Promise<{ node: AgentNode; state: AgentGraphState; steps: number }> {
216	  let node: AgentNode = startNode;
217	  let current = state;
218	  let steps = startStep;
219	  while (node !== "done" && steps < MAX_STEPS) {
220	    const result = await stepGraph(node, current, deps);
221	    node = result.node;
222	    current = result.state;
223	    steps++;
224	    if (onStep) await onStep(node, current, result.event);
225	  }
226	  if (node !== "done") {
227	    current = { ...current, errors: [...current.errors, `step budget exhausted (${MAX_STEPS})`] };
228	  }
229	  return { node, state: current, steps };
230	}

760	  return city ? ` location:"${city}"` : "";
761	}
762	
763	/**
764	 * Shared live-generation attempt for follow-up / re-contact drafts — the same
765	 * three-layer fallback generateOutreachLive/regenerateOutreach already use (a
766	 * cloud provider or hermes live mode configured -> hermesGenerate -> parse ->
767	 * humanize). Without this, draftFollowUpFor/draftRecontactFor always fell
768	 * straight to the mock template, so every follow-up touch for a candidate was
769	 * byte-identical copy. Returns the mock unchanged (live: false) on any
770	 * failure at any layer — a follow-up draft always lands regardless.
771	 */
772	async function attemptLiveFollowUpGen(opts: {
773	  settings: SystemSettings;
774	  candidate: Candidate;
775	  campaign: Campaign;
776	  tone: OutreachTone;
777	  channel: OutreachChannel;
778	  voice?: { persona?: string; signature?: string };
779	  lang: string;
780	  mockGen: GeneratedOutreach;
781	  seat?: AgentSeat;
782	  touchNote: string;
783	}): Promise<{ gen: GeneratedOutreach; live: boolean }> {
784	  const { settings, candidate, campaign, tone, channel, voice, lang, mockGen, seat, touchNote } = opts;
785	  const aiCfg = resolveAiProvider(settings, "outreach", {
786	    providerId: seat?.providerId,
787	    modelId: seat?.modelId,
788	  });
789	  if (!aiCfg && !(settings.hermesLiveMode && hermesAvailable(settings))) {
790	    return { gen: mockGen, live: false };
791	  }
792	
793	  const basePrompt = buildOutreachPrompt({
794	    candidateName: candidate.name,
795	    candidateTitle: candidate.currentTitle,
796	    candidateCompany: candidate.currentCompany,
797	    techStack: candidate.techStack,
798	    recentActivity: candidate.recentActivity,
799	    yearsExperience: candidate.yearsExperience,
800	    roleTitle: campaign.jobAnalysis.title,
801	    locationType: campaign.jobAnalysis.locationType,
802	    regions: campaign.jobAnalysis.regions,
803	    requiredSkills: campaign.jobAnalysis.requiredSkills,
804	    tone,
805	    channel,
806	    language: lang,
807	    persona: voice?.persona,
808	    signature: voice?.signature,
809	  });
